WITH supplier_summary AS (SELECT supplier_id, COUNT(DISTINCT cost) AS unique_categorys, SUM(CASE WHEN brand = 'Umbrella' THEN stock_qty ELSE 0 END) AS umbrella_stock_qty FROM products GROUP BY supplier_id) SELECT s.country, s.supplier_name, ss.unique_categorys, ss.umbrella_stock_qty FROM suppliers s INNER JOIN supplier_summary ss ON s.id = ss.supplier_id ORDER BY unique_categorys DESC;
